typedef unsigned int nlUint32;
typedef int nlInt32;
typedef nlUint32 nslSourceId;
typedef nlUint32 nslSoundId;
typedef nlUint32 nslEmitterId;

typedef enum _nslSoundParamEnum
{
  NSL_SOUNDPARAM_VOLUME,
  NSL_SOUNDPARAM_PITCH,
  NSL_SOUNDPARAM_MINDIST,
  NSL_SOUNDPARAM_MAXDIST,
  NSL_SOUNDPARAM_Z
} nslSoundParamEnum;

extern "C" void nslFatal(const char *, ...);

struct nslSource
{
  char prefix[0x3c];
  nslSourceId myId;
  char middle[0x0c];
  nlUint32 gasSourceId;
  float rawVolume;
  float pitch;
  float minDist;
  float maxDist;
};

struct nslSound
{
  bool isReady;
  bool used;
  bool inRange;
  bool isReallyReady;
  bool isPlaying;
  bool isReallyPlaying;
  bool looping;
  bool isQueuing;
  short left;
  short right;
  short old_left;
  short old_right;
  nlUint32 gasInstanceId;
  nlInt32 pauseCount;
  nlInt32 dampenCount;
  nslSoundId myId;
  nslSourceId mySource;
  nslEmitterId myEmitter;
  float rawVolume;
  float positionalVolume;
  float angle;
  float pitch;
  float minDist;
  float maxDist;
};

struct nslSystem
{
  char listenerPo[0x40];
  nslSource sourceSlots[512];
  nslSound soundSlots[256];
  char afterSounds[0x400c];
  nlInt32 initialized;
  char beforeOn[0x2c];
  bool on;
};

extern nslSystem nsl;
__asm__(".equ nsl, 0x0049B5F0");
__asm__(".equ nslFatal__FPCce, 0x00391420");

inline void _nslCheckSourceIdValidity(nslSourceId checkId)
{
  nslSourceId checkSlot = (checkId & 0x0000FFFF);
  nslSourceId upCheckId = (checkId & 0xFFFF0000);
  nlUint32 gasId = nsl.sourceSlots[checkSlot].gasSourceId;
  nlUint32 negativeOne = (nlUint32)-1;
  if (!(checkId != 0)) nslFatal("This source id is the INVALID id");
  if (!(gasId != negativeOne)) nslFatal("This source has a bad GAS id");
  if (!(checkSlot < 512)) nslFatal("This source is above the max number of sources");
  if (!(checkId == nsl.sourceSlots[checkSlot].myId)) nslFatal("This ID passed does not match the id for the source slot");
  if (!(upCheckId > 0)) nslFatal("THE INSTANCE PART OF THE ID IS NOT > 0");
  if (checkSlot > 512) nslFatal("THE SLOT PART IS MORE THAN THE NUMBER OF TOTAL SLOTS");
}

inline void _nslCheckSoundIdValidity(nslSoundId checkId)
{
  nslSoundId checkSlot = (checkId & 0x000003FF);
  nslSoundId upCheckId = (checkId & 0xFFFFFC00);
  if (checkId == 0) nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (!(nsl.soundSlots[checkSlot].used)) nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (!(checkSlot < 256)) nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (!(checkId == nsl.soundSlots[checkSlot].myId)) nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (!(upCheckId > 0)) nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (checkSlot > 256) nslFatal("Bad Sound ID 0x%x SLOT NUMBER ABOVE SLOTS\n", checkId);
}

inline void _nslInitialized()
{
  if (!(nsl.initialized == 1)) nslFatal("NSL NOT INITIALIZED");
}

#define ASSERT_NSL_INITIALIZED() _nslInitialized()
#define ASSERT_SOURCE_ID_VALID(x) _nslCheckSourceIdValidity(x)
#define ASSERT_SOUND_ID_VALID(x) _nslCheckSoundIdValidity(x)
#define NSL_GET_SLOT_FROM_ID(x) (x&0x000003FF)

void nslSetSoundParam( nslSoundId soundToSet, nslSoundParamEnum whichParam,
                       float newVal )
{
  if (!nsl.on) return;
  ASSERT_NSL_INITIALIZED();
  ASSERT_SOURCE_ID_VALID(nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToSet)].mySource);
  ASSERT_SOUND_ID_VALID(soundToSet);

  switch (whichParam) {
    case NSL_SOUNDPARAM_VOLUME:
      if (newVal > 1.0f)
        newVal = 1.0f;
      nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToSet)].rawVolume=newVal; break;
    case NSL_SOUNDPARAM_PITCH:
      nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToSet)].pitch=newVal; break;
    case NSL_SOUNDPARAM_MINDIST:
      nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToSet)].minDist=newVal; break;
    case NSL_SOUNDPARAM_MAXDIST:
      nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToSet)].maxDist=newVal; break;
    default: nslFatal(false && "Unhandled sourcetype"); break;
  }
}
